powerpagecomponent.content:
{
  "source": "{% comment %}
sections--acceptance-venue

- acceptanceId passed from router (or URL param fallback)
- Hero image: hit_isprimary = true on hit_venuespaceimage
- Space tab: hit_description rendered as HTML (supports <ul> feature list)
- Availability: calendar driven by bookings / holds / blackouts (date-only)
- Inclusions: categorised tick/cross list from hit_venuespaceinclusion
- Images: 3-col grid with captions
- Form: ORGANISATION DETAILS / PRIMARY CONTACT / BOOKING DETAILS
- Submit: PATCH acceptance (contact + status PENDING_APPROVAL) then
          POST one hit_venuespacebookingrequest per date entry
- Multiple Dates mode: one booking request per date
{% endcomment %}

{% assign debugMode = debug | default: request.params.debug | default: '' | strip %}
{% assign acceptanceId = acceptanceId | default: request.params.acceptanceid | default: '' | strip %}

{% if acceptanceId == '' %}
  <div class="hit-alert hit-alert-error">Missing acceptance id.</div>
{% else %}

  {%- comment -%} 1. Acceptance record {%- endcomment -%}
  {% fetchxml acc_q %}
  <fetch top="1" mapping="logical">
    <entity name="hit_offeringacceptance">
      <attribute name="hit_offeringacceptanceid" />
      <attribute name="hit_firstname" />
      <attribute name="hit_lastname" />
      <attribute name="hit_email" />
      <attribute name="hit_mobilephone" />
      <attribute name="hit_organisationinput" />
      <attribute name="hit_contactroleinput" />
      <attribute name="hit_offering" />
      <filter>
        <condition attribute="hit_offeringacceptanceid" operator="eq" value="{{ acceptanceId }}" />
      </filter>
    </entity>
  </fetch>
  {% endfetchxml %}

  {% assign acc = acc_q.results.entities | first %}

  {% if acc == nil %}
    <div class="hit-alert hit-alert-error">Acceptance record not found.</div>
  {% else %}

    {% assign offeringId = acc.hit_offering.id %}

    {%- comment -%} 2. Offering -> venue space ID {%- endcomment -%}
    {% fetchxml off_q %}
    <fetch top="1">
      <entity name="hit_offering">
        <attribute name="hit_offeringname" />
        <attribute name="hit_venuespace" />
        <filter>
          <condition attribute="hit_offeringid" operator="eq" value="{{ offeringId }}" />
        </filter>
      </entity>
    </fetch>
    {% endfetchxml %}

    {% assign off    = off_q.results.entities | first %}
    {% assign vs_id  = off.hit_venuespace.id %}

    {% if vs_id == blank %}
      <div class="hit-alert hit-alert-error">No venue space is linked to this offering.</div>
    {% else %}

      {%- comment -%} 3. Venue space (all capacity fields) {%- endcomment -%}
      {% fetchxml vs_q %}
      <fetch top="1">
        <entity name="hit_venuespace">
          <attribute name="hit_name" />
          <attribute name="hit_displaytitle" />
          <attribute name="hit_description" />
          <attribute name="hit_capacitystanding" />
          <attribute name="hit_capacityseated" />
          <attribute name="hit_capacitytheatre" />
          <attribute name="hit_capacityboardroom" />
          <attribute name="hit_capacityushape" />
          <attribute name="hit_capacityworkshop" />
          <filter>
            <condition attribute="hit_venuespaceid" operator="eq" value="{{ vs_id }}" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {% assign venuespace      = vs_q.results.entities | first %}
      {% assign venuespace_name = venuespace.hit_displaytitle | default: venuespace.hit_name | default: 'Venue Space' %}
      {% assign venuespace_desc = venuespace.hit_description | default: '' %}

      {%- comment -%} Safely extract numeric capacity values {%- endcomment -%}
      {% assign cap_standing  = venuespace.hit_capacitystanding  | default: 0 %}
      {% assign cap_theatre   = venuespace.hit_capacitytheatre   | default: 0 %}
      {% assign cap_boardroom = venuespace.hit_capacityboardroom | default: 0 %}
      {% assign cap_ushape    = venuespace.hit_capacityushape    | default: 0 %}
      {% assign cap_workshop  = venuespace.hit_capacityworkshop  | default: 0 %}
      {% if cap_standing.value  %}{% assign cap_standing  = cap_standing.value  %}{% endif %}
      {% if cap_theatre.value   %}{% assign cap_theatre   = cap_theatre.value   %}{% endif %}
      {% if cap_boardroom.value %}{% assign cap_boardroom = cap_boardroom.value %}{% endif %}
      {% if cap_ushape.value    %}{% assign cap_ushape    = cap_ushape.value    %}{% endif %}
      {% if cap_workshop.value  %}{% assign cap_workshop  = cap_workshop.value  %}{% endif %}

      {%- comment -%} 4. Primary hero image (hit_isprimary = true) {%- endcomment -%}
      {% fetchxml hero_q %}
      <fetch top="1">
        <entity name="hit_venuespaceimage">
          <attribute name="hit_imageurl" />
          <attribute name="hit_name" />
          <filter>
            <condition attribute="hit_venuespace" operator="eq" value="{{ vs_id }}" />
            <condition attribute="hit_isprimary" operator="eq" value="1" />
            <condition attribute="statecode" operator="eq" value="0" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {% assign hero_img = hero_q.results.entities | first %}
      {% assign hero_url = hero_img.hit_imageurl | default: '' %}

      {%- comment -%} 5. All venue images (gallery) {%- endcomment -%}
      {% fetchxml images_q %}
      <fetch>
        <entity name="hit_venuespaceimage">
          <attribute name="hit_imageurl" />
          <attribute name="hit_name" />
          <order attribute="hit_sortorder" descending="false" />
          <filter>
            <condition attribute="hit_venuespace" operator="eq" value="{{ vs_id }}" />
            <condition attribute="statecode" operator="eq" value="0" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {%- comment -%} 6. Inclusions {%- endcomment -%}
      {% fetchxml inclusions_q %}
      <fetch>
        <entity name="hit_venuespaceinclusion">
          <attribute name="hit_name" />
          <attribute name="hit_defaultincluded" />
          <attribute name="hit_venueinclusioncategory" />
          <order attribute="hit_venueinclusioncategory" descending="false" />
          <order attribute="hit_name" descending="false" />
          <filter>
            <condition attribute="hit_venuespace" operator="eq" value="{{ vs_id }}" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {%- comment -%} 7. Bookings / holds / blackouts for calendar {%- endcomment -%}
      {% fetchxml bookings_q %}
      <fetch>
        <entity name="hit_venuespacebooking">
          <attribute name="hit_startdatetime" />
          <attribute name="hit_enddatetime" />
          <filter>
            <condition attribute="hit_venuespace" operator="eq" value="{{ vs_id }}" />
            <condition attribute="statecode" operator="eq" value="0" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {% fetchxml holds_q %}
      <fetch>
        <entity name="hit_venuespacehold">
          <attribute name="hit_startdatetime" />
          <attribute name="hit_enddatetime" />
          <filter>
            <condition attribute="hit_venuespace" operator="eq" value="{{ vs_id }}" />
            <condition attribute="statecode" operator="eq" value="0" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {% fetchxml blackouts_q %}
      <fetch>
        <entity name="hit_venuespaceblackout">
          <attribute name="hit_startdatetime" />
          <attribute name="hit_enddatetime" />
          <filter>
            <condition attribute="hit_venuespace" operator="eq" value="{{ vs_id }}" />
            <condition attribute="statecode" operator="eq" value="0" />
          </filter>
        </entity>
      </fetch>
      {% endfetchxml %}

      {% if debugMode == '1' %}
      <div style="padding:10px 12px;margin:10px 0;border-radius:8px;background:#eef2ff;border:1px solid #c7d2fe;font-family:ui-monospace,monospace;font-size:12px;">
        acceptanceId={{ acceptanceId | escape }}<br>
        vs_id={{ vs_id | escape }} | venuespace={{ venuespace_name | escape }}<br>
        hero={{ hero_url | escape }}<br>
        images={{ images_q.results.entities.size }} | inclusions={{ inclusions_q.results.entities.size }}<br>
        bookings={{ bookings_q.results.entities.size }} | holds={{ holds_q.results.entities.size }} | blackouts={{ blackouts_q.results.entities.size }}<br>
        cap: standing={{ cap_standing }} theatre={{ cap_theatre }} boardroom={{ cap_boardroom }} ushape={{ cap_ushape }} workshop={{ cap_workshop }}
      </div>
      {% endif %}

<section class="section section--acceptance-venue">
<style>
/* ============================================================
   VENUE BOOKING LAYOUT  (TODO: extract to css--site.css)
   ============================================================ */
.section--acceptance-venue { padding: 0; }
.venue-booking {
  display: grid;
  grid-template-columns: 1fr 420px;
  gap: 32px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 32px 20px;
  align-items: start;
}
@media (max-width: 960px) {
  .venue-booking { grid-template-columns: 1fr; }
  .venue-booking__form-col { position: static !important; }
}
.venue-booking__heading { margin: 0 0 20px; font-size: 26px; font-weight: 800; letter-spacing: -0.02em; color: #111827; }

/* Tabs */
.vb-tabs { background:#fff; border:1px solid #e8e8e8; border-radius:14px; overflow:hidden; box-shadow:0 4px 14px rgba(0,0,0,.05); }
.vb-tabs__nav { display:flex; border-bottom:1px solid #e8e8e8; padding:0 16px; }
.vb-tab-btn { padding:14px 16px; border:none; background:none; cursor:pointer; font-size:14px; font-weight:600; color:#6b7280; border-bottom:2px solid transparent; margin-bottom:-1px; transition:color 140ms,border-color 140ms; white-space:nowrap; }
.vb-tab-btn:hover { color:#111827; }
.vb-tab-btn.active { color:#111827; border-bottom-color:#111827; }
.vb-tab-panel { display:none; padding:20px; }
.vb-tab-panel.active { display:block; }

/* Space tab */
.venue-hero { width:100%; aspect-ratio:16/9; object-fit:cover; border-radius:10px; margin-bottom:16px; background:#f3f4f6; display:block; }
.venue-description { font-size:15px; line-height:1.7; color:#374151; }
.venue-description ul { margin:12px 0 0; padding-left:20px; }
.venue-description li { margin-bottom:6px; }

/* Calendar */
.vb-calendar__header { display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; }
.vb-calendar__title { font-weight:800; font-size:15px; color:#111827; }
.vb-calendar__nav { background:#f6f6f6; border:1px solid #e6e6e6; border-radius:8px; padding:7px 12px; cursor:pointer; font-size:14px; transition:background 120ms; }
.vb-calendar__nav:hover { background:#efefef; }
.vb-calendar__dow { display:grid; grid-template-columns:repeat(7,1fr); gap:4px; margin-bottom:4px; }
.vb-calendar__dow-label { text-align:center; font-size:11px; font-weight:700; color:#9ca3af; text-transform:uppercase; padding:4px 0; }
.vb-calendar__grid { display:grid; grid-template-columns:repeat(7,1fr); gap:4px; }
.vb-cal-day { aspect-ratio:1; display:flex; align-items:center; justify-content:center; border-radius:8px; font-size:13px; font-weight:600; cursor:pointer; border:1px solid #f0f0f0; background:#fff; color:#111827; transition:background 120ms,transform 80ms; user-select:none; }
.vb-cal-day:hover:not(.is-past):not(.is-booked) { background:#f0f0f0; transform:translateY(-1px); }
.vb-cal-day.is-past { color:#d1d5db; background:#fafafa; cursor:default; border-color:transparent; }
.vb-cal-day.is-booked { background:#e9e9e9; color:#9ca3af; cursor:not-allowed; }
.vb-cal-day.is-held { background:#fff3e0; border-color:#ffd3a6; color:#92400e; }
.vb-cal-day.is-selected { background:#111827; color:#fff; border-color:#111827; }

/* Inclusions */
.incl-group { margin-bottom:16px; }
.incl-group__title { font-size:11px; font-weight:800; letter-spacing:.06em; text-transform:uppercase; color:#6b7280; margin:0 0 8px; padding-bottom:6px; border-bottom:1px solid #f0f0f0; }
.incl-list { list-style:none; padding:0; margin:0; display:grid; gap:6px; }
.incl-item { display:flex; align-items:center; gap:10px; font-size:14px; color:#374151; }
.incl-icon { width:20px; height:20px; border-radius:50%; display:flex; align-items:center; justify-content:center; font-size:11px; font-weight:900; flex:0 0 20px; }
.incl-icon.yes { background:#ecfdf5; color:#047857; }
.incl-icon.no  { background:#fef2f2; color:#b91c1c; }

/* Images */
.vb-image-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; }
@media (max-width:600px) { .vb-image-grid { grid-template-columns:repeat(2,1fr); } }
.vb-image-figure { margin:0; }
.vb-image-figure img { width:100%; aspect-ratio:4/3; object-fit:cover; border-radius:8px; border:1px solid #f0f0f0; background:#f3f4f6; display:block; }
.vb-image-figure figcaption { font-size:12px; color:#6b7280; text-align:center; margin-top:5px; }

/* Form card */
.venue-booking__form-col { position:sticky; top:100px; }
.vb-form-card { background:#fff; border:1px solid #e8e8e8; border-radius:14px; box-shadow:0 6px 20px rgba(0,0,0,.07); overflow:hidden; }
.vb-form-card__header { padding:16px 20px; background:linear-gradient(180deg,#f9fafb 0%,#fff 100%); border-bottom:1px solid #f0f0f0; }
.vb-form-card__title { margin:0; font-size:16px; font-weight:800; color:#111827; }
.vb-form-card__body { padding:20px; }

/* Form elements */
.vbf-section-title { font-size:11px; font-weight:800; letter-spacing:.06em; text-transform:uppercase; color:#6b7280; margin:16px 0 10px; }
.vbf-section-title:first-child { margin-top:0; }
.vbf-row { display:grid; grid-template-columns:1fr 1fr; gap:10px; }
@media (max-width:480px) { .vbf-row { grid-template-columns:1fr; } }
.vbf-group { display:grid; gap:5px; margin-bottom:10px; }
.vbf-label { font-size:12px; font-weight:700; color:#374151; }
.vbf-control { width:100%; padding:9px 12px; border-radius:8px; border:1px solid #d9d9d9; background:#fff; font-size:14px; color:#111827; outline:none; transition:border-color 140ms,box-shadow 140ms; box-sizing:border-box; }
.vbf-control:focus { border-color:#1f2937; box-shadow:0 0 0 3px rgba(31,41,55,.1); }
textarea.vbf-control { resize:vertical; min-height:80px; }

/* Radios */
.vbf-radio-group { display:flex; flex-wrap:wrap; gap:14px; margin-bottom:10px; }
.vbf-radio-label { display:flex; align-items:center; gap:6px; font-size:13px; font-weight:600; color:#374151; cursor:pointer; }
.vbf-radio-label input[type="radio"] { accent-color:#111827; width:15px; height:15px; cursor:pointer; }

/* Layout cards */
.vbf-layout-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; margin-bottom:10px; }
.vbf-layout-card { padding:10px 8px; border:1px solid #e5e7eb; border-radius:8px; background:#fff; cursor:pointer; text-align:center; transition:border-color 140ms,background 140ms,transform 80ms; user-select:none; }
.vbf-layout-card:hover { border-color:#9ca3af; background:#f9fafb; }
.vbf-layout-card:active { transform:translateY(1px); }
.vbf-layout-card.is-selected { border-color:#111827; background:#f8fafc; box-shadow:0 0 0 2px #111827; }
.vbf-layout-card__name { font-size:13px; font-weight:700; color:#111827; display:block; }
.vbf-layout-card__cap  { font-size:11px; color:#6b7280; margin-top:2px; display:block; }

/* Submit */
.vbf-submit { width:100%; padding:13px; background:#111827; color:#fff; border:none; border-radius:10px; font-size:14px; font-weight:800; cursor:pointer; margin-top:14px; transition:opacity 140ms,transform 80ms; }
.vbf-submit:hover { opacity:.9; }
.vbf-submit:active { transform:translateY(1px); }
.vbf-submit:disabled { opacity:.55; cursor:not-allowed; }

/* Alerts */
.vbf-alert { padding:10px 12px; border-radius:8px; font-size:13px; margin-bottom:10px; border:1px solid transparent; }
.vbf-alert--error { background:#fff1f2; border-color:#fecdd3; color:#9f1239; }
.hit-alert { padding:12px 16px; border-radius:10px; font-size:14px; border:1px solid transparent; }
.hit-alert-error { background:#fff1f2; border-color:#fecdd3; color:#9f1239; }

/* Date input visibility */
#vb-dates-single,#vb-dates-range,#vb-dates-multi { display:none; }
#vb-dates-single.active,#vb-dates-range.active,#vb-dates-multi.active { display:block; }
.vb-multi-date-list { display:grid; gap:8px; margin-bottom:8px; }
.vb-multi-date-item { display:flex; gap:8px; align-items:center; }
.vb-multi-date-item .vbf-control { flex:1; }
.vb-multi-date-remove { background:none; border:none; color:#9ca3af; cursor:pointer; font-size:16px; line-height:1; padding:4px; flex:0 0 auto; }
.vb-multi-date-remove:hover { color:#ef4444; }
.vb-add-date-btn { background:none; border:1px dashed #d1d5db; border-radius:8px; color:#6b7280; font-size:13px; font-weight:600; padding:8px 12px; cursor:pointer; width:100%; transition:border-color 140ms,color 140ms; }
.vb-add-date-btn:hover { border-color:#6b7280; color:#374151; }
</style>

<div class="venue-booking">

  <!-- ==========================================================
       LEFT: INFO TABS
       ========================================================== -->
  <div class="venue-booking__info-col">

    <h1 class="venue-booking__heading">Book {{ venuespace_name | escape }}</h1>

    <div class="vb-tabs">

      <div class="vb-tabs__nav" role="tablist">
        <button type="button" class="vb-tab-btn active" data-tab="space" role="tab" aria-selected="true">Space</button>
        <button type="button" class="vb-tab-btn" data-tab="availability" role="tab" aria-selected="false">Availability</button>
        <button type="button" class="vb-tab-btn" data-tab="inclusions" role="tab" aria-selected="false">Inclusions</button>
        <button type="button" class="vb-tab-btn" data-tab="images" role="tab" aria-selected="false">Images</button>
      </div>

      <!-- SPACE -->
      <div class="vb-tab-panel active" id="vb-tab-space" role="tabpanel">
        {% if hero_url != '' %}
          <img src="{{ hero_url | escape }}" alt="{{ venuespace_name | escape }}" class="venue-hero" />
        {% endif %}
        {% if venuespace_desc != '' %}
          <div class="venue-description">{{ venuespace_desc }}</div>
        {% else %}
          <p style="color:#9ca3af;font-size:14px;margin:0;">Description coming soon.</p>
        {% endif %}
      </div>

      <!-- AVAILABILITY -->
      <div class="vb-tab-panel" id="vb-tab-availability" role="tabpanel">
        <div class="vb-calendar__header">
          <button type="button" class="vb-calendar__nav" id="vbCalPrev" aria-label="Previous month">&#8592;</button>
          <div class="vb-calendar__title" id="vbCalTitle"></div>
          <button type="button" class="vb-calendar__nav" id="vbCalNext" aria-label="Next month">&#8594;</button>
        </div>
        <div class="vb-calendar__dow" aria-hidden="true">
          <div class="vb-calendar__dow-label">Su</div>
          <div class="vb-calendar__dow-label">Mo</div>
          <div class="vb-calendar__dow-label">Tu</div>
          <div class="vb-calendar__dow-label">We</div>
          <div class="vb-calendar__dow-label">Th</div>
          <div class="vb-calendar__dow-label">Fr</div>
          <div class="vb-calendar__dow-label">Sa</div>
        </div>
        <div class="vb-calendar__grid" id="vbCalGrid"></div>
      </div>

      <!-- INCLUSIONS -->
      <div class="vb-tab-panel" id="vb-tab-inclusions" role="tabpanel">
        {% assign all_incl = inclusions_q.results.entities %}
        {% if all_incl.size == 0 %}
          <p style="color:#9ca3af;font-size:14px;margin:0;">No inclusions found.</p>
        {% else %}
          {% assign current_cat = '' %}
          {% for inc in all_incl %}
            {% assign cat = inc.hit_venueinclusioncategory.label | default: 'Other' %}
            {% if cat != current_cat %}
              {% if current_cat != '' %}</ul></div>{% endif %}
              {% assign current_cat = cat %}
              <div class="incl-group">
              <p class="incl-group__title">{{ cat | escape }}</p>
              <ul class="incl-list">
            {% endif %}
            {% assign included = inc.hit_defaultincluded == true or inc.hit_defaultincluded == 1 %}
            <li class="incl-item">
              <span class="incl-icon {% if included %}yes{% else %}no{% endif %}" aria-hidden="true">{% if included %}&#10003;{% else %}&#10005;{% endif %}</span>
              {{ inc.hit_name | escape }}
            </li>
          {% endfor %}
          {% if current_cat != '' %}</ul></div>{% endif %}
        {% endif %}
      </div>

      <!-- IMAGES -->
      <div class="vb-tab-panel" id="vb-tab-images" role="tabpanel">
        <div class="vb-image-grid">
          {% for img in images_q.results.entities %}
            {% assign imgUrl = img.hit_imageurl | default: '' %}
            {% if imgUrl != '' %}
              <figure class="vb-image-figure">
                <img src="{{ imgUrl | escape }}" alt="{{ img.hit_name | default: venuespace_name | escape }}" loading="lazy" />
                {% if img.hit_name != blank %}<figcaption>{{ img.hit_name | escape }}</figcaption>{% endif %}
              </figure>
            {% endif %}
          {% endfor %}
        </div>
      </div>

    </div>
  </div>

  <!-- ==========================================================
       RIGHT: BOOKING FORM
       ========================================================== -->
  <div class="venue-booking__form-col">
    <div class="vb-form-card">

      <div class="vb-form-card__header">
        <h2 class="vb-form-card__title">Reserve this space</h2>
      </div>

      <div class="vb-form-card__body">

        <div id="vbErrBox" class="vbf-alert vbf-alert--error" style="display:none;" role="alert"></div>

        <form id="vbForm" novalidate>

          <input type="hidden" id="vbAcceptanceId" value="{{ acc.hit_offeringacceptanceid | escape }}" />
          <input type="hidden" id="vbVenueSpaceId" value="{{ vs_id | escape }}" />
          <input type="hidden" id="vbSelectedLayout" value="" />

          <!-- ORGANISATION DETAILS -->
          <p class="vbf-section-title">Organisation Details</p>

          <div class="vbf-group">
            <label class="vbf-label" for="vbOrgName">Organisation Name</label>
            <input class="vbf-control" type="text" id="vbOrgName"
                   value="{{ acc.hit_organisationinput | default: '' | escape }}"
                   autocomplete="organization" />
          </div>

          <div class="vbf-group">
            <label class="vbf-label" for="vbRole">Your Role</label>
            <select class="vbf-control" id="vbRole">
              <option value="">&#8212; Select role &#8212;</option>
              <option value="Coordinator"{% if acc.hit_contactroleinput == 'Coordinator' %} selected{% endif %}>Coordinator</option>
              <option value="Event Manager"{% if acc.hit_contactroleinput == 'Event Manager' %} selected{% endif %}>Event Manager</option>
              <option value="Director / Executive"{% if acc.hit_contactroleinput == 'Director / Executive' %} selected{% endif %}>Director / Executive</option>
              <option value="Other"{% if acc.hit_contactroleinput == 'Other' %} selected{% endif %}>Other</option>
            </select>
          </div>

          <!-- PRIMARY CONTACT -->
          <p class="vbf-section-title">Primary Contact</p>

          <div class="vbf-row">
            <div class="vbf-group">
              <label class="vbf-label" for="vbFirstName">First Name</label>
              <input class="vbf-control" type="text" id="vbFirstName"
                     value="{{ acc.hit_firstname | default: '' | escape }}"
                     autocomplete="given-name" required />
            </div>
            <div class="vbf-group">
              <label class="vbf-label" for="vbLastName">Last Name</label>
              <input class="vbf-control" type="text" id="vbLastName"
                     value="{{ acc.hit_lastname | default: '' | escape }}"
                     autocomplete="family-name" required />
            </div>
          </div>

          <div class="vbf-group">
            <label class="vbf-label" for="vbEmail">Email Address</label>
            <input class="vbf-control" type="email" id="vbEmail"
                   value="{{ acc.hit_email | default: '' | escape }}"
                   autocomplete="email" required />
          </div>

          <div class="vbf-group">
            <label class="vbf-label" for="vbMobile">Mobile Number</label>
            <input class="vbf-control" type="tel" id="vbMobile"
                   value="{{ acc.hit_mobilephone | default: '' | escape }}"
                   autocomplete="tel" />
          </div>

          <!-- BOOKING DETAILS -->
          <p class="vbf-section-title">Booking Details</p>

          <div class="vbf-group">
            <label class="vbf-label">Booking Type</label>
            <div class="vbf-radio-group">
              <label class="vbf-radio-label"><input type="radio" name="vbBookingType" value="single" checked /> Single Date</label>
              <label class="vbf-radio-label"><input type="radio" name="vbBookingType" value="range" /> Date Range</label>
              <label class="vbf-radio-label"><input type="radio" name="vbBookingType" value="multiple" /> Multiple Dates</label>
            </div>
          </div>

          <div id="vb-dates-single" class="active">
            <div class="vbf-group">
              <label class="vbf-label" for="vbDateSingle">Date</label>
              <input class="vbf-control" type="date" id="vbDateSingle" />
            </div>
          </div>

          <div id="vb-dates-range">
            <div class="vbf-row">
              <div class="vbf-group">
                <label class="vbf-label" for="vbDateFrom">From</label>
                <input class="vbf-control" type="date" id="vbDateFrom" />
              </div>
              <div class="vbf-group">
                <label class="vbf-label" for="vbDateTo">To</label>
                <input class="vbf-control" type="date" id="vbDateTo" />
              </div>
            </div>
          </div>

          <div id="vb-dates-multi">
            <label class="vbf-label" style="margin-bottom:8px;display:block;">Dates</label>
            <div class="vb-multi-date-list" id="vbMultiDateList">
              <div class="vb-multi-date-item">
                <input class="vbf-control vb-multi-date-input" type="date" />
                <button type="button" class="vb-multi-date-remove" aria-label="Remove date">&#10005;</button>
              </div>
            </div>
            <button type="button" class="vb-add-date-btn" id="vbAddDateBtn">+ Add another date</button>
          </div>

          <div class="vbf-group" style="margin-top:10px;">
            <label class="vbf-label">Session Type</label>
            <div class="vbf-radio-group">
              <label class="vbf-radio-label"><input type="radio" name="vbSessionType" value="Full Day" checked /> Full Day</label>
              <label class="vbf-radio-label"><input type="radio" name="vbSessionType" value="Morning" /> Morning</label>
              <label class="vbf-radio-label"><input type="radio" name="vbSessionType" value="Afternoon" /> Afternoon</label>
            </div>
          </div>

          <div class="vbf-group">
            <label class="vbf-label">Preferred Venue Layout</label>
            <div class="vbf-layout-grid">
              {% if cap_standing > 0 %}
              <div class="vbf-layout-card" data-layout="Standing">
                <span class="vbf-layout-card__name">Standing</span>
                <span class="vbf-layout-card__cap">Up to {{ cap_standing }}</span>
              </div>
              {% endif %}
              {% if cap_theatre > 0 %}
              <div class="vbf-layout-card" data-layout="Theatre">
                <span class="vbf-layout-card__name">Theatre</span>
                <span class="vbf-layout-card__cap">Up to {{ cap_theatre }}</span>
              </div>
              {% endif %}
              {% if cap_boardroom > 0 %}
              <div class="vbf-layout-card" data-layout="Boardroom">
                <span class="vbf-layout-card__name">Boardroom</span>
                <span class="vbf-layout-card__cap">Up to {{ cap_boardroom }}</span>
              </div>
              {% endif %}
              {% if cap_ushape > 0 %}
              <div class="vbf-layout-card" data-layout="U-Shape">
                <span class="vbf-layout-card__name">U-Shape</span>
                <span class="vbf-layout-card__cap">Up to {{ cap_ushape }}</span>
              </div>
              {% endif %}
              {% if cap_workshop > 0 %}
              <div class="vbf-layout-card" data-layout="Workshop">
                <span class="vbf-layout-card__name">Workshop</span>
                <span class="vbf-layout-card__cap">Up to {{ cap_workshop }}</span>
              </div>
              {% endif %}
            </div>
          </div>

          <div class="vbf-group">
            <label class="vbf-label" for="vbEventDesc">Briefly Describe Your Event</label>
            <textarea class="vbf-control" id="vbEventDesc"
                      placeholder="Tell us about the purpose of your event, expected attendees and any special requirements."></textarea>
          </div>

          <button type="submit" id="vbSubmitBtn" class="vbf-submit">Reserve Booking</button>

        </form>
      </div>
    </div>
  </div>

</div>

<script>
(function () {

  var DEBUG = {% if debugMode == '1' %}true{% else %}false{% endif %};
  function dbg(label, data) {
    if (!DEBUG) return;
    try { console.log('[venue-booking] ' + label, data !== undefined ? data : ''); } catch(e) {}
  }

  var _acceptanceId = "{{ acc.hit_offeringacceptanceid | default: '' | escape }}";
  var _vsId         = "{{ vs_id | default: '' | escape }}";

  var bookings = [{% for b in bookings_q.results.entities %}{ start:"{{ b.hit_startdatetime | date: '%Y-%m-%d' }}", end:"{{ b.hit_enddatetime | date: '%Y-%m-%d' }}" }{% unless forloop.last %},{% endunless %}{% endfor %}];
  var holds    = [{% for h in holds_q.results.entities %}{ start:"{{ h.hit_startdatetime | date: '%Y-%m-%d' }}", end:"{{ h.hit_enddatetime | date: '%Y-%m-%d' }}" }{% unless forloop.last %},{% endunless %}{% endfor %}];
  var blackouts= [{% for bl in blackouts_q.results.entities %}{ start:"{{ bl.hit_startdatetime | date: '%Y-%m-%d' }}", end:"{{ bl.hit_enddatetime | date: '%Y-%m-%d' }}" }{% unless forloop.last %},{% endunless %}{% endfor %}];

  dbg('init', { acceptanceId: _acceptanceId, vsId: _vsId, bookings: bookings.length, holds: holds.length, blackouts: blackouts.length });

  /* -------- TABS -------- */
  document.querySelectorAll('.vb-tab-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      document.querySelectorAll('.vb-tab-btn').forEach(function(b) { b.classList.remove('active'); b.setAttribute('aria-selected','false'); });
      document.querySelectorAll('.vb-tab-panel').forEach(function(p) { p.classList.remove('active'); });
      btn.classList.add('active');
      btn.setAttribute('aria-selected','true');
      var panel = document.getElementById('vb-tab-' + btn.dataset.tab);
      if (panel) panel.classList.add('active');
      if (btn.dataset.tab === 'availability') renderCalendar();
    });
  });

  /* -------- CALENDAR -------- */
  var calDate = new Date();
  var selectedDate = null;

  function inRange(str, s, e) { return str >= s && str <= e; }
  function isBooked(str) {
    return bookings.some(function(b){ return inRange(str,b.start,b.end); }) ||
           blackouts.some(function(b){ return inRange(str,b.start,b.end); });
  }
  function isHeld(str) { return holds.some(function(h){ return inRange(str,h.start,h.end); }); }

  function renderCalendar() {
    var grid  = document.getElementById('vbCalGrid');
    var title = document.getElementById('vbCalTitle');
    if (!grid || !title) return;
    var y = calDate.getFullYear(), m = calDate.getMonth();
    var today = new Date().toISOString().split('T')[0];
    title.textContent = calDate.toLocaleString('default',{month:'long',year:'numeric'});
    var firstDay = new Date(y,m,1).getDay(), daysInMonth = new Date(y,m+1,0).getDate();
    var html = '';
    for (var i=0; i<firstDay; i++) html += '<div></div>';
    for (var d=1; d<=daysInMonth; d++) {
      var str = y + '-' + String(m+1).padStart(2,'0') + '-' + String(d).padStart(2,'0');
      var cls = 'vb-cal-day';
      if (str < today)          cls += ' is-past';
      else if (isBooked(str))   cls += ' is-booked';
      else if (isHeld(str))     cls += ' is-held';
      if (str === selectedDate) cls += ' is-selected';
      html += '<div class="' + cls + '" data-date="' + str + '">' + d + '</div>';
    }
    grid.innerHTML = html;
    grid.querySelectorAll('.vb-cal-day:not(.is-past):not(.is-booked)').forEach(function(el) {
      el.addEventListener('click', function() {
        selectedDate = el.dataset.date;
        var si = document.getElementById('vbDateSingle');
        if (si) si.value = el.dataset.date;
        renderCalendar();
      });
    });
  }

  document.getElementById('vbCalPrev').addEventListener('click', function() { calDate.setMonth(calDate.getMonth()-1); renderCalendar(); });
  document.getElementById('vbCalNext').addEventListener('click', function() { calDate.setMonth(calDate.getMonth()+1); renderCalendar(); });
  renderCalendar();

  /* -------- BOOKING TYPE -------- */
  document.querySelectorAll('input[name="vbBookingType"]').forEach(function(r) {
    r.addEventListener('change', function() {
      ['single','range','multiple'].forEach(function(t) {
        document.getElementById('vb-dates-' + t).classList.remove('active');
      });
      document.getElementById('vb-dates-' + r.value).classList.add('active');
    });
  });

  /* -------- MULTIPLE DATES -------- */
  function attachRemove(btn) {
    btn.addEventListener('click', function() {
      var item = btn.closest('.vb-multi-date-item');
      var list = document.getElementById('vbMultiDateList');
      if (list && list.querySelectorAll('.vb-multi-date-item').length > 1) item.remove();
    });
  }
  document.querySelectorAll('.vb-multi-date-remove').forEach(attachRemove);
  document.getElementById('vbAddDateBtn').addEventListener('click', function() {
    var item = document.createElement('div');
    item.className = 'vb-multi-date-item';
    item.innerHTML = '<input class="vbf-control vb-multi-date-input" type="date" />' +
                     '<button type="button" class="vb-multi-date-remove" aria-label="Remove date">&#10005;</button>';
    document.getElementById('vbMultiDateList').appendChild(item);
    attachRemove(item.querySelector('.vb-multi-date-remove'));
  });

  /* -------- LAYOUT CARDS -------- */
  document.querySelectorAll('.vbf-layout-card').forEach(function(card) {
    card.addEventListener('click', function() {
      document.querySelectorAll('.vbf-layout-card').forEach(function(c) { c.classList.remove('is-selected'); });
      card.classList.add('is-selected');
      var h = document.getElementById('vbSelectedLayout');
      if (h) h.value = card.dataset.layout;
    });
  });

  /* -------- HELPERS -------- */
  function val(id) { var el = document.getElementById(id); return el ? el.value.trim() : ''; }

  function showErr(msg) {
    var box = document.getElementById('vbErrBox');
    if (!box) return;
    box.textContent = msg;
    box.style.display = 'block';
    box.scrollIntoView({ behavior:'smooth', block:'nearest' });
  }
  function clearErr() {
    var box = document.getElementById('vbErrBox');
    if (box) { box.style.display='none'; box.textContent=''; }
  }
  function setSubmitting(busy) {
    var btn = document.getElementById('vbSubmitBtn');
    if (!btn) return;
    btn.disabled = busy;
    btn.textContent = busy ? 'Submitting…' : 'Reserve Booking';
  }

  var SESSION_HOURS = { 'Full Day':{s:8,e:18}, 'Morning':{s:8,e:12}, 'Afternoon':{s:13,e:17} };
  function buildISO(dateStr, h) { return dateStr + 'T' + String(h).padStart(2,'0') + ':00:00'; }

  async function getCsrfToken() {
    try {
      var res = await fetch('/_api/GetAccessToken', { method:'POST', credentials:'same-origin' });
      var d   = await res.json();
      return d.value;
    } catch(e) { console.error('CSRF token failed', e); return null; }
  }

  async function parseApiError(res) {
    try { var d = await res.json(); if (d&&d.error&&d.error.message) return d.error.message; } catch(e) {}
    return 'An error occurred. Please try again.';
  }

  /* -------- SUBMIT -------- */
  document.getElementById('vbForm').addEventListener('submit', async function(e) {
    e.preventDefault();
    clearErr();

    if (!_acceptanceId) { showErr('Acceptance ID is missing.'); return; }

    var firstName = val('vbFirstName');
    var lastName  = val('vbLastName');
    var email     = val('vbEmail');
    var mobile    = val('vbMobile');
    var orgName   = val('vbOrgName');
    var roleEl    = document.getElementById('vbRole');
    var role      = roleEl ? roleEl.value : '';

    if (!firstName) { showErr('First name is required.'); return; }
    if (!lastName)  { showErr('Last name is required.'); return; }
    if (!email)     { showErr('Email address is required.'); return; }

    var bookingTypeEl = document.querySelector('input[name="vbBookingType"]:checked');
    var bookingType   = bookingTypeEl ? bookingTypeEl.value : 'single';
    var sessionTypeEl = document.querySelector('input[name="vbSessionType"]:checked');
    var sessionType   = sessionTypeEl ? sessionTypeEl.value : 'Full Day';
    var hours         = SESSION_HOURS[sessionType] || SESSION_HOURS['Full Day'];
    var layout        = val('vbSelectedLayout');
    var eventDesc     = val('vbEventDesc');

    var dateEntries = [];
    if (bookingType === 'single') {
      var d = val('vbDateSingle');
      if (!d) { showErr('Please select a date.'); return; }
      dateEntries.push({ start:d, end:d });
    } else if (bookingType === 'range') {
      var from = val('vbDateFrom'), to = val('vbDateTo');
      if (!from||!to)  { showErr('Please select a start and end date.'); return; }
      if (from > to)   { showErr('Start date must be before end date.'); return; }
      dateEntries.push({ start:from, end:to });
    } else {
      document.querySelectorAll('.vb-multi-date-input').forEach(function(inp) {
        if (inp.value) dateEntries.push({ start:inp.value, end:inp.value });
      });
      if (dateEntries.length === 0) { showErr('Please add at least one date.'); return; }
    }

    dbg('submit', { bookingType:bookingType, sessionType:sessionType, dates:dateEntries, layout:layout });
    setSubmitting(true);

    try {
      var token = await getCsrfToken();
      if (!token) { showErr('Security token could not be loaded. Please refresh and try again.'); setSubmitting(false); return; }

      /* 1. PATCH acceptance */
      var patchPayload = {
        hit_firstname:         firstName,
        hit_lastname:          lastName,
        hit_email:             email,
        hit_mobilephone:       mobile  || null,
        hit_organisationinput: orgName || null,
        hit_contactroleinput:  role    || null,
        hit_acceptancestatus:  815390002
      };
      dbg('PATCH', patchPayload);

      var patchRes = await fetch('/_api/hit_offeringacceptances(' + _acceptanceId + ')', {
        method:'PATCH', credentials:'same-origin',
        headers:{ 'Content-Type':'application/json', '__RequestVerificationToken':token, 'If-Match':'*' },
        body: JSON.stringify(patchPayload)
      });
      if (!patchRes.ok) { showErr(await parseApiError(patchRes)); setSubmitting(false); return; }
      dbg('PATCH', '✅');

      /* 2. POST booking request(s) */
      for (var i=0; i<dateEntries.length; i++) {
        var entry = dateEntries[i];
        var bookingPayload = {
          'hit_VenueSpace@odata.bind':        '/hit_venuespaces('          + _vsId        + ')',
          'hit_OfferingAcceptance@odata.bind': '/hit_offeringacceptances(' + _acceptanceId + ')',
          hit_startdatetime:   buildISO(entry.start, hours.s),
          hit_enddatetime:     buildISO(entry.end,   hours.e),
          hit_sessiontype:     sessionType,
          hit_preferredlayout: layout    || null,
          hit_notes:           eventDesc || null
        };
        dbg('POST booking ' + (i+1), bookingPayload);
        var postRes = await fetch('/_api/hit_venuespacebookingrequests', {
          method:'POST', credentials:'same-origin',
          headers:{ 'Content-Type':'application/json', '__RequestVerificationToken':token },
          body: JSON.stringify(bookingPayload)
        });
        if (!postRes.ok) { showErr(await parseApiError(postRes)); setSubmitting(false); return; }
        dbg('POST booking ' + (i+1), '✅');
      }

      window.location.href = '/confirmation/?acceptanceId=' + encodeURIComponent(_acceptanceId);

    } catch(err) {
      console.error('Venue booking error:', err);
      showErr('An unexpected error occurred. Please try again.');
      setSubmitting(false);
    }
  });

})();
</script>

</section>

    {% endif %}
  {% endif %}
{% endif %}"
}
